SELECT p.code FROM sys_role_permission rp JOIN sys_permission p ON rp.permission_id=p.id WHERE rp.role_id=1 AND (p.code LIKE '%customer%' OR p.code LIKE '%competitor%' OR p.code LIKE '%pool%' OR p.code LIKE '%quote%' OR p.code LIKE '%contract%' OR p.code LIKE '%log%' OR p.code LIKE '%product%' OR p.code LIKE '%purchase%' OR p.code LIKE '%opportunity%' OR p.code LIKE '%follow%') ORDER BY p.code;
